insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"About","heading":"An SEO Agency That Only Does SEO","body":"Jordan Marketing Consultants used to do everything. In 2022 it stopped, and kept the one service it was genuinely good at. Everything on this site is search visibility, explained in plain language every month."}'::jsonb, 0 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'became', 'timeline', 'white', '{"eyebrow":"History","heading":"What JMC Has Become","body":"The agency did not start here. It arrived at one service by taking things away.","entries":[{"year":"Before the agency","title":"Sales, then the web","body":"A decade in sales and business development, including building and training sales teams from the ground up, before any of the work was digital."},{"year":"The full-service years","title":"Web design was the main business","body":"A full-service agency doing web design, hosting, and everything adjacent to it. SEO was one line item among many."},{"year":"2022","title":"One service","body":"The agency stopped offering everything else and kept the one thing it was genuinely good at."},{"year":"Today","title":"Local, regional, and industrial search","body":"Search visibility for businesses around Houston and beyond, with the same four-question recap every month on every engagement."}]}'::jsonb, 1 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'narrowing', 'featureSplit', 'surface', '{"eyebrow":"2022","heading":"The Narrowing","body":"JMC used to be full service, with web design as the main business. The websites were not good enough, and the process from onboarding to launch was difficult for everyone involved.\n\nThe turn came in a professional networking group. SEO was the only part of the work worth talking about. Over time it became the part worth doing.\n\nIn 2022 the agency stopped doing everything and started doing one thing.","portrait":{"src":"/images/wendell-jordan.png","alt":"Wendell Jordan","shape":"circle","name":"Wendell Jordan","role":"Founder","bio":"Wendell has spent more than a decade running a digital marketing agency, the last several years of it on SEO alone. He came to the work from sales and business development, which is where the insistence on plain reporting comes from: he spent years explaining numbers to people who did not want a dashboard."},"groups":[]}'::jsonb, 2 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'scope', 'cardGrid', 'white', '{"eyebrow":"Scope","heading":"What JMC Does, and What It Doesn''t","body":"The boundary is the same on every engagement, and it is easier to point at than to describe.","columns":2,"cards":[{"title":"What JMC Does","icon":"search","items":["Local SEO","Traditional SEO","Google Business Profile","Technical monitoring","Strategic SEO pages and written content","Reporting and monthly recaps"]},{"title":"What JMC Doesn''t Do","icon":"layers","items":["Paid ads","Web design","Social media posts","Link building and link placements"]}]}'::jsonb, 3 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-jmc-works', 'cardGrid', 'surface', '{"variant":"compact","eyebrow":"How JMC Works","heading":"You Work With the People Doing the Work","columns":3,"cards":[{"title":"A Small Senior Team","icon":"users","body":"No account-manager layer, and no handoff to juniors once the contract is signed."},{"title":"Direct Access","icon":"message-square","body":"The person who answers a question about your campaign is the person running it."},{"title":"A TREC-Approved Instructor","icon":"shield-check","body":"Wendell Jordan teaches a TREC-approved continuing education class for Texas real estate licensees."}]}'::jsonb, 4 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'league-city', 'fullWidthText', 'white', '{"eyebrow":"Based in League City","heading":"League City, Texas","body":"JMC is based in League City and works with businesses across the Houston area and beyond. Being nearby helps with understanding a market. It has never been a limit on who the work is for."}'::jsonb, 5 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'surface', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month, on every engagement.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 6 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Look at Where Your Visibility Stands","body":"A Visibility Review is the first step on every engagement, and it is useful even when it ends in advice rather than a contract.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 7 from public.pages where slug = '/about';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"Monthly SEO Packages","heading":"The Prices Are on This Page","body":"Six monthly packages across two service lines, with what each one includes and what it costs. Nothing here is behind a call, because a price you have to ask for is a price that changes depending on who is asking.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 0 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'path', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Start Here","heading":"Two Paths, Sorted by Reach","body":"Which one fits comes down to where a business competes, not how large it is.","cards":[{"title":"Local SEO","icon":"map-pin","meta":"From $875 a month","body":"For businesses competing for customers in a defined area, however many locations they run inside it.","cta":{"label":"View Local SEO Packages","href":"#local"}},{"title":"Traditional SEO","icon":"globe","meta":"From $2,295 a month","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"View Traditional SEO Packages","href":"#traditional"}}]}'::jsonb, 1 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local', 'pricingCards', 'white', '{"eyebrow":"Local SEO","heading":"Local SEO Packages","body":"Three tiers, sized by how much ground you are competing for.","packageIds":["local-neighborhood","local-citywide","local-metro"]}'::jsonb, 2 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local-included', 'cardGrid', 'white', '{"variant":"compact","columns":3,"eyebrow":"Every Local Tier","heading":"Included in Every Local Package","body":"The three tiers differ by volume, not by what is included.","cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"A plan for the quarter, with the reasoning behind the order."},{"title":"Content & On-Page Optimization","icon":"pencil","body":"Service pages, titles, descriptions and page structure."},{"title":"Technical Monitoring","icon":"gauge","body":"Crawling, indexing and site health watched month to month."},{"title":"Detailed Monthly Reporting","icon":"bar-chart","body":"What was tracked, what moved, and what did not."},{"title":"Monthly Project Recap","icon":"message-square","body":"Delivered by Loom or a video call, with room to ask questions."},{"title":"Review Management","icon":"star","body":"Requests sent to real customers, and replies to what arrives."}]}'::jsonb, 3 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local-custom', 'fullWidthText', 'white', '{"heading":"Bigger Than Metro?","body":"If the scope is bigger or more involved than what is here, JMC will look at it and put together a quote. That is still a Local engagement, however many locations are involved.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional', 'pricingCards', 'surface', '{"eyebrow":"Traditional SEO","heading":"Traditional SEO Packages","body":"Three tiers, sized by footprint rather than by headcount.","packageIds":["traditional-regional","traditional-national","traditional-national-plus"]}'::jsonb, 5 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional-included', 'cardGrid', 'surface', '{"variant":"compact","columns":3,"eyebrow":"Every Traditional Tier","heading":"Included in Every Traditional Package","body":"The three tiers differ by footprint, not by what is included.","cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"The same plan, applied across markets rather than an area."},{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for specific searches, produced to a schedule."},{"title":"Technical Monitoring","icon":"gauge","body":"Issues flagged as they appear, not found in an annual audit."},{"title":"Reporting & Monthly Recap","icon":"bar-chart","body":"Dashboard reporting alongside the recap, in both cases explained."},{"title":"Authority-Building Recommendations","icon":"network","body":"Advice on what would strengthen authority. Recommendations, not link placements."}]}'::jsonb, 6 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional-custom', 'fullWidthText', 'surface', '{"heading":"Bigger Than National+?","body":"If the footprint is wider or the search landscape more competitive than what is published here, JMC will look at the scope and put together a quote rather than forcing it into a tier that does not fit.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 7 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'onboarding', 'featureSplit', 'white', '{"align":"left","eyebrow":"The One-Time Fee","heading":"What Onboarding Covers","body":"Every tier carries a one-time onboarding fee, from $349 to $1,295 depending on the package. It pays for the work that has to happen once before the monthly work means anything: nothing built on an unaudited foundation is worth reporting on.\n\nThe two scopes are genuinely different rather than one generic setup with two price tags. Switch between them to see what each one actually covers.\n\nA Launch Sprint is this same work bought standalone, which is why it waives the fee rather than discounting it. The next section sets out which sprint waives which package.","tabs":[{"label":"Local SEO","items":[{"title":"Kickoff and access setup","body":"Accounts, permissions and the handover needed before anything can be audited."},{"title":"Local SEO audit","body":"The current foundation reviewed end to end, with findings ranked by impact."},{"title":"Local keyword and competitor snapshot","body":"What the business should be found for, and who is currently being found instead."},{"title":"Search Console and Bing setup","body":"Set up or verified, so the reporting has something real behind it from month one."},{"title":"Google Business Profile audit and core optimization","body":"Categories, services, hours and the fields that decide whether the profile shows at all."},{"title":"Citation audit and NAP standard","body":"One agreed name, address and phone format, and a list of where it is currently wrong."},{"title":"Schema, sitemap and robots.txt review","body":"The technical files that decide what search engines can read."},{"title":"Titles and meta descriptions","body":"Written for the priority pages rather than generated across the whole site."},{"title":"Local search grid baseline","body":"Where the business ranks across the service area today, so later months have something to compare against."}]},{"label":"Traditional SEO","items":[{"title":"Kickoff and access setup","body":"Accounts, permissions and the handover needed before anything can be audited."},{"title":"Technical and on-page SEO audit","body":"A full review across the site rather than a local profile, since the competition is not in one area."},{"title":"Keyword and competitor analysis","body":"Across every market and service line in scope, not a single radius."},{"title":"Search Console and Bing setup","body":"Set up or verified, so the reporting has something real behind it from month one."},{"title":"Schema, sitemap and robots.txt review","body":"The technical files that decide what search engines can read."},{"title":"Titles and meta descriptions","body":"Written for the priority pages rather than generated across the whole site."},{"title":"Backlink audit","body":"What authority already exists and what is actively working against it."}]}],"groups":[],"cta":{"label":"Get Started","href":"/contact"}}'::jsonb, 8 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprint-waiver', 'waiverMatrix', 'surface', '{"eyebrow":"Another Way In","heading":"Start With a Launch Sprint","body":"A sprint is the onboarding work done standalone, with a roadmap attached. That is why the waiver exists rather than being a discount: it is close to the same job, bought once, with no monthly commitment behind it.","sprintHeading":"Sprint","priceHeading":"One-time","waivesHeading":"Waives onboarding on","rows":[{"sprint":"Neighborhood Launch Sprint","price":"$799","waives":"Neighborhood, Citywide, or Metro"},{"sprint":"Regional Launch Sprint","price":"$1,495","waives":"Regional"},{"sprint":"National Launch Sprint","price":"$2,295","waives":"National or National+"}],"condition":"Monthly service must begin within 30 calendar days of sprint completion.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 9 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"Included in every package in both lanes, at every tier.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 10 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Pricing Questions","items":[{"question":"Why a 12-month term?","answer":"Because SEO compounds and a short engagement cannot show what a full one can. Most of the foundational work lands in the first quarter and most of the return on it arrives later, so a three-month contract would mean paying for the setup and leaving before the benefit. The term applies to all six monthly tiers in both lanes."},{"question":"What happens after 12 months?","answer":"It runs month to month from then on, for as long as you want it to, and either side can end it with 30 days written notice. There is no second term and no automatic re-commitment."},{"question":"What does the onboarding fee cover?","answer":"On Local: the audit, tracking setup, foundational optimization and the local visibility setup, meaning profile, categories, services, citations and the grid baseline. On Traditional: the audit, tracking setup, foundational optimization and roadmap development. A Launch Sprint can waive it entirely if monthly service begins within 30 days of the sprint finishing."},{"question":"Can tiers be changed later?","answer":"Upgrades happen any time. The deliverables adjust from the next cycle and there is no additional onboarding fee. Downgrades take effect at renewal rather than mid-term."},{"question":"Which lane fits?","answer":"Reach decides it, not size. A business competing for customers in a defined area is Local, however many locations it runs there. A business competing across markets, service lines or competitive search is Traditional. Both service pages set out the difference in more detail."},{"question":"Does this include blog content?","answer":"Yes. Strategic SEO Pages covers all written SEO content, blog posts included. Early phases usually prioritise local and industry pages first, simply because blog content needs somewhere to point before it does much good."},{"question":"What is not included?","answer":"Paid advertising, web design and development, social media posting, and link building. Authority building is covered as recommendations rather than as placements bought on your behalf."},{"question":"Is there anything without a term?","answer":"Launch Sprints. One-time, completed within 30 days, no term and no renewal, ending with a roadmap that is yours whatever you decide next."},{"question":"Can Local and Traditional be combined?","answer":"Yes, as a custom plan. It is usually scoped from the Local deliverable side with the Traditional work layered on, and it needs a conversation rather than a package number."},{"question":"What if none of these fit?","answer":"Larger or more involved scopes get a custom quote. That is a real answer rather than a polite one: several kinds of engagement genuinely do not fit into three tiers."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 11 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Not Sure Which One Fits?","body":"A visibility review covers where you appear now, what is holding it back, and which package or sprint actually matches the problem.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 12 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Home Services & Trades","heading":"SEO for Home Services and Trades","body":"Home service searches are urgent, local, and mostly made on a phone. Getting found in that moment is a different problem from ranking for a term someone researches over a fortnight.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"coverage","label":"How buyers search","title":"Urgent and Nearby","items":["On a phone","Outside business hours","Inside a drive-time radius","Decided in minutes"]},{"kind":"coverage","label":"What it rests on","title":"Profile and Listings","items":["Map pack","Categories","Reviews"]}]}'::jsonb, 0 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":5,"eyebrow":"Who This Is For","heading":"The Trades This Applies To","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"HVAC & Climate Control","icon":"gauge","body":"Demand spikes with the weather, and the searches that come with it are almost always urgent. Visibility has to already be there when the heat arrives."},{"title":"Power Washing & Exterior Cleaning","icon":"storefront","body":"A seasonal, price-comparable service where the first few businesses a homeowner finds usually get the quote requests."},{"title":"Roofing & Exterior Remodeling","icon":"home","body":"High-value jobs with a longer decision than most trades, and a spike in searches after every storm."},{"title":"Electrical & Plumbing Trades","icon":"lightning","body":"A split between emergency calls and planned work, and the two are searched for in completely different language."},{"title":"Landscaping & Tree Services","icon":"wrench","body":"Recurring and one-off work side by side, usually chosen within a tight drive-time radius."}]}'::jsonb, 1 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in the Trades","body":"Trades searches are mostly emergencies, and an emergency search behaves nothing like a considered one. Someone whose air conditioning has failed in August is on a phone, will call one of the first businesses they see, and will not open a second page of results. Storm damage does the same thing to roofing at a larger scale, and it happens with no notice.\n\nThe buying cycle is short, often minutes. That makes the map pack and the profile more valuable here than almost anywhere else, and it makes an incomplete listing an expensive problem rather than a tidy-up job. Competition is usually local, which is the good news: the field is the businesses inside the same drive-time radius, not every company in the state.","groups":[{"title":"Phone first, and often after hours","icon":"phone","body":"The searches that convert best arrive outside business hours and end in a tap on a phone number."},{"title":"Seasonal spikes with no warning","icon":"lightning","body":"Weather sets the calendar. Visibility has to be built before the spike, because there is no time to build it during one."},{"title":"Won or lost inside the map pack","icon":"map-pin","body":"For urgent work the profile carries more weight than the website, so the two have to agree with each other."}]}'::jsonb, 2 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'fullWidthText', 'surface', '{"eyebrow":"Where to Start","heading":"This Work Sits in Local SEO","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth.\n\nHome Services & Trades businesses compete inside a defined area, and the profile, the map pack and the reviews attached to them decide most of it. The work belongs in local search rather than spread thin across markets the business does not sell into.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}'::jsonb, 3 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. For a trades business the answers are about map pack position, the service area, and whether you were visible before the season turned.","did":"The work completed that month, named task by task: profile posts, service-area pages, citation corrections, and the seasonal content queued before its season rather than during it.","why":"Why that work came first, which is usually either a service about to peak or a part of the service area ranking well behind the rest of it.","changed":"Map pack position across the service area, which urgent-intent searches moved, and call volume wherever it is being tracked. Reported honestly, including the months where little moved.","next":"Next month''s priorities, with the following seasonal spike already in the plan instead of noticed once it has started.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Home Services & Trades Questions","items":[{"question":"How quickly can a trades business expect to see movement?","answer":"Local work tends to move faster than national search because the competing field is smaller, but there is no honest way to promise a date. Profile and listing corrections can show up within weeks; content and authority work is a longer arc, and the recap tells you which one you are watching each month."},{"question":"Does a service-area business without a storefront rank differently?","answer":"Yes. A service-area business hides its address and is ranked against the area it covers rather than a pin on a map, which makes the service area definition, the categories, and consistent listings do more of the work."},{"question":"Is it worth doing SEO if most work comes from referrals?","answer":"Usually. Referrals get searched for by name before anyone calls, and a weak profile or a thin website loses jobs that were already won. That is often the cheapest fix on the list."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in home services & trades?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/home-services-trades';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Healthcare & Wellness","heading":"SEO for Healthcare and Wellness Practices","body":"Patients research before they book, and they usually stop at the first practice that looks credible and close. Visibility and reputation do the work together here.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"growth","label":"How patients search","title":"By Symptom, Not Specialty","items":["What hurts, in plain words","Somewhere close by","Checked against reviews","Booked, or abandoned"]},{"kind":"coverage","label":"What it rests on","title":"Reputation and Access","items":["Reviews","Photos","Booking path"]}]}'::jsonb, 0 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"compact","columns":4,"eyebrow":"Who This Is For","heading":"Practices This Applies To","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"Mental & Behavioral Health Professionals","icon":"users","body":"Searched for privately and carefully, often by specialty and modality rather than by practice name."},{"title":"Private Dental & Medical Practices","icon":"heart-pulse","body":"Among the most competitive local categories anywhere, with searches split between routine care and urgent problems."},{"title":"Physical Therapy & Sports Rehab","icon":"shield-check","body":"Referral-heavy, but nearly every referral gets checked online before an appointment is made."},{"title":"Medical Spas & Wellness Clinics","icon":"star","body":"A discretionary purchase where reviews, photos and the profile carry as much weight as the website."}]}'::jsonb, 1 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Healthcare","body":"Patients search by symptom and by condition far more than by specialty. Somebody types what hurts, not the clinical name for the practitioner who fixes it, and the gap between those two vocabularies is where most practice websites lose traffic they should have had.\n\nThe cycle is short but not instant. A patient will usually look at two or three practices, check reviews on each, glance at photographs, and book the one that feels closest to both an answer and a location. That makes the profile, the reviews and the appointment path part of the SEO problem rather than separate from it. Competition is local and dense, particularly in dentistry, so the difference between the third and the first result is measured in booked appointments.","groups":[{"title":"Searched by symptom, not by specialty","icon":"search","body":"Content has to meet the language patients actually use before it can rank for it."},{"title":"Reviews are read before the site is","icon":"star","body":"Reputation and visibility are the same job here, which is why review support sits inside the packages."},{"title":"Booking friction undoes the ranking","icon":"calendar","body":"Being found first is worth little if the next step is a phone number and an answering machine."}]}'::jsonb, 2 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'fullWidthText', 'surface', '{"eyebrow":"Where to Start","heading":"This Work Sits in Local SEO","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth.\n\nHealthcare & Wellness businesses compete inside a defined area, and the profile, the map pack and the reviews attached to them decide most of it. The work belongs in local search rather than spread thin across markets the business does not sell into.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}}'::jsonb, 3 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. For a practice the answers are about symptom language, reputation, and whether the booking path survives the click.","did":"The work completed that month, named task by task: condition and symptom pages, profile and review work, and fixes to the path between a search and a booked appointment.","why":"Why that work came first, which is usually a condition the practice should be found for and is not, or a step in the booking path losing people who had already chosen it.","changed":"Which symptom and condition searches moved, how the profile and reviews are tracking, and where appointment enquiries arrived from. Reported honestly, including the months where little moved.","next":"Next month''s priorities in order, so the practice is never the last to find out what is being worked on.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Healthcare & Wellness Questions","items":[{"question":"Can a practice site rank without publishing medical advice?","answer":"Yes. Most of the useful traffic comes from service, condition and location pages describing what the practice treats and how a patient starts, rather than from clinical articles that need a physician to write and review them."},{"question":"How are patient reviews handled?","answer":"Packages include review request sends and replies. Nothing is fabricated or incentivised, and no review is ever written on a practice''s behalf, which would breach both the platform rules and the positioning this agency is built on."},{"question":"Does a multi-location practice need separate pages?","answer":"Usually yes. Each location needs its own profile, its own consistent listings, and enough of its own content that the two locations are not competing with each other in the same results."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in healthcare & wellness?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/healthcare-wellness';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Hospitality & Attractions","heading":"SEO for Hospitality and Attractions","body":"Hospitality search runs on two clocks at once: someone deciding where to eat in ten minutes, and someone planning a visit six weeks out. The same business has to be visible in both.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"},"showcase":[{"kind":"report","label":"Two clocks at once","title":"Now, and Six Weeks Out","items":["Deciding on a street","Planning a weekend","Comparing across tabs","Booking direct, or not"]},{"kind":"coverage","label":"What it rests on","title":"Listings and Detail","items":["Hours","Photos","Menus and pages"]}]}'::jsonb, 0 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'who-this-is-for', 'cardGrid', 'surface', '{"variant":"cards","columns":4,"eyebrow":"Who This Is For","heading":"Places This Applies To","body":"The kinds of business this applies to. Naming a category is not a claim of expertise in it.","cards":[{"title":"RV Parks & Campground Resorts","icon":"map-pin","body":"Booked weeks ahead by people comparing sites, amenities and location across a whole region."},{"title":"Regional Venues & Event Spaces","icon":"calendar","body":"A long, considered booking with a high value, researched across many sites before anyone makes contact."},{"title":"Coastal & Waterway Attractions","icon":"ship","body":"Draws visitors from well outside the immediate area, which pulls the work beyond a single local radius."},{"title":"Boutique Hotels & Lodging","icon":"building","body":"Competing against booking platforms that outrank almost everyone, so direct visibility has to be earned in the gaps they leave."}]}'::jsonb, 1 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'search-behaviour', 'featureSplit', 'white', '{"align":"left","eyebrow":"Search Behaviour","heading":"What Search Looks Like in Hospitality","body":"Hospitality is two industries wearing one coat. A restaurant is found by someone standing on a street with ten minutes of patience, where hours, photographs and the map listing settle it before the website is opened. A venue or a hotel is found by someone planning weeks ahead, comparing options across a dozen tabs, and reading far more than a listing.\n\nThe second kind is where the reach question decides the service. A neighbourhood restaurant competes inside a few miles. A destination attraction or a wedding venue draws from a whole region and competes with businesses in other cities for the same visit, which is a different problem with a different set of pages behind it. Booking platforms sit on top of many of these results, so part of the work is finding the searches they do not dominate.","groups":[{"title":"Two clocks, one business","icon":"calendar","body":"Immediate searches and planned ones need different pages and different language."},{"title":"Photos and hours decide the click","icon":"image","body":"Profile content is not housekeeping here. It is the deciding factor on the highest-volume searches."},{"title":"Reach varies wildly by format","icon":"globe","body":"A local bar and a regional attraction are not the same engagement, which is why neither lane is assumed."}]}'::jsonb, 2 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'how-it-works', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Where to Start","heading":"Two Ways In, Sorted by Reach","body":"The method does not change with the industry. What changes is the search language, the priorities, and what a single lead is worth. Which service fits a hospitality & attractions business comes down to where it competes, not how big it is.","cards":[{"title":"Local SEO","icon":"map-pin","body":"For businesses competing for customers in a defined area, however many locations they run in it.","cta":{"label":"Explore Local SEO","href":"/local-seo-services"}},{"title":"Traditional SEO","icon":"globe","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"Explore Traditional SEO","href":"/traditional-seo-services"}}]}'::jsonb, 3 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"The same four questions every month. For a venue the answers run on two clocks at once: tonight''s searches and the ones happening six weeks out.","did":"The work completed that month, named task by task: listing detail, photographs and hours, event and seasonal pages, and the content built for bookings that get planned well in advance.","why":"Why that work came first, which is usually a season approaching or a listing detail quietly costing clicks that the ranking had already earned.","changed":"What moved on the immediate searches and on the planning-ahead ones separately, because they rarely move together. Reported honestly, including the months where little moved.","next":"Next month''s priorities, with the next booking window already accounted for rather than arriving as a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 4 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Hospitality Questions","items":[{"question":"Is this a local or a regional problem?","answer":"It depends on where guests come from. A neighbourhood restaurant is Local SEO. An attraction or venue that draws from across the region competes across markets, which points toward Traditional SEO. That question gets answered in the review rather than assumed from the category."},{"question":"Can SEO compete with the booking platforms?","answer":"Not by outranking them everywhere. It works by taking the searches they handle badly, particularly branded, specific and planning-stage queries, and by making the direct booking path the obvious one once someone has found you."},{"question":"How much does the Google Business Profile matter?","answer":"More than in almost any other sector. Hours, photographs, menu links and attributes are read directly in the results by people who never reach the website, so a stale profile costs visits outright."},{"question":"Which service fits a business like this?","answer":"It depends on reach rather than size. If the customers are in a defined area, that is Local SEO, however many locations are involved. If the business competes across several markets or service lines, that is Traditional SEO. A visibility review sorts it in one conversation."},{"question":"Does JMC specialise in hospitality & attractions?","answer":"No, and that is deliberate. A specialist charges for pattern-matching from other clients in your sector, which JMC does not pretend to have yet. What is on offer instead is a method that works regardless of sector, and reporting clear enough that you can see whether it is working."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/industries/hospitality-attractions';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears today, which searches it is missing, and which of those gaps is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 6 from public.pages where slug = '/industries/hospitality-attractions';
